package com.cognia.api.application.service;
import static org.junit.jupiter.api.Assertions.*;
import com.cognia.api.application.port.out.*; import com.cognia.api.domain.model.*; import com.cognia.api.domain.service.*; import java.util.*; import org.junit.jupiter.api.Test;
class LearningPathServiceTest {
	@Test void recalculatingAnIdenticalRouteDoesNotCreateANewVersion(){var student=UUID.randomUUID();var subject=UUID.randomUUID();var concept=UUID.randomUUID();var step=new PathStep(UUID.randomUUID(),concept,0,PathStep.State.DISPONIBLE);var active=new LearningPath(UUID.randomUUID(),student,subject,2,LearningPath.State.ACTIVA,List.of(step));var paths=new FakePaths(active);var service=new LearningPathService(paths,new FakeEvaluations(),new FakeDiagnostics(student,subject),id->true,new FakeSubjects(subject),new FakeConcepts(subject,concept),new FakePrerequisites(),new FakeActivities(),new ActivityCorrectionService(),new RuleBasedMasteryPolicy(Map.of(1,1d,2,1.5,3,2d)),.8,70,2);var recalculated=service.recalculate(student,subject);assertEquals(2,recalculated.version());assertEquals(0,paths.saved);assertEquals(0,paths.updated);}
	private static class FakePaths implements LearningPathRepository {LearningPath path;int saved,updated;FakePaths(LearningPath p){path=p;}public Optional<LearningPath> active(UUID s,UUID a){return Optional.ofNullable(path).filter(p->p.state()==LearningPath.State.ACTIVA);}public Optional<LearningPath> byId(UUID id){return Optional.ofNullable(path);}public Optional<LearningPath> latest(UUID s,UUID a){return Optional.ofNullable(path);}public LearningPath save(LearningPath p){saved++;return p;}public LearningPath update(LearningPath p){updated++;path=p;return p;}public List<PathStep> saveSteps(UUID id,List<PathStep> s){return s;}}
	private static class FakeEvaluations implements ShortEvaluationRepository {public Optional<ShortEvaluation> inProgress(UUID s,UUID p){return Optional.empty();}public Optional<ShortEvaluation> find(UUID id){return Optional.empty();}public int nextAttempt(UUID s,UUID c){return 1;}public int consecutiveFailures(UUID s,UUID p){return 0;}public int reinforcementDifficulty(UUID s,UUID p){return 1;}public ShortEvaluation save(ShortEvaluation s){return s;}public List<EvaluationAnswer> answers(UUID s){return List.of();}public EvaluationAnswer saveAnswer(UUID s,UUID a,UUID o,String t,boolean c,Integer sec){return null;}}
	private static class FakeDiagnostics implements DiagnosticRepository {final UUID student,subject,profile=UUID.randomUUID();FakeDiagnostics(UUID s,UUID a){student=s;subject=a;}public Optional<DiagnosticSession> findInProgress(UUID s,UUID a){return Optional.empty();}public boolean hasCompleted(UUID s,UUID a){return false;}public DiagnosticSession saveSession(DiagnosticSession s){return s;}public Optional<DiagnosticSession> findSession(UUID id){return Optional.empty();}public List<DiagnosticAnswer> answers(UUID id){return List.of();}public DiagnosticAnswer saveAnswer(DiagnosticAnswer a){return a;}public UUID ensureProfile(UUID s,UUID a){return profile;}public void completeProfile(UUID id){}public KnowledgeProfile profile(UUID s,UUID a){return new KnowledgeProfile(profile,student,subject,true,List.of());}public Optional<ConceptMastery> mastery(UUID p,UUID c){return Optional.empty();}public ConceptMastery saveMastery(UUID p,ConceptMastery m){return m;}public void saveHistory(UUID p,UUID c,double old,double next,MasteryChangeSource src,UUID session){}}
	private static class FakeSubjects implements SubjectRepository {final UUID subject;FakeSubjects(UUID id){subject=id;}public List<Subject> findAll(){return List.of();}public Optional<Subject> findById(UUID id){return id.equals(subject)?Optional.of(new Subject(id,"MAT","Math",null,true)):Optional.empty();}}
	private static class FakeConcepts implements ConceptRepository {final UUID subject,concept;FakeConcepts(UUID s,UUID c){subject=s;concept=c;}public List<Concept> findBySubjectId(UUID id){return List.of(new Concept(concept,subject,"C1","Concept",null,1,0,true));}public Optional<Concept> findById(UUID id){return findBySubjectId(subject).stream().filter(c->c.id().equals(id)).findFirst();}}
	private static class FakePrerequisites implements PrerequisiteRepository {public List<Prerequisite> findByConceptId(UUID id){return List.of();}public List<Prerequisite> findBySubjectId(UUID id){return List.of();}public Prerequisite save(Prerequisite p){return p;}}
	private static class FakeActivities implements ActivityRepository {public List<Activity> findPracticeByConcept(UUID c,Integer d){return List.of();}public List<Activity> findDiagnosticBySubject(UUID s){return List.of();}public Optional<Activity> findById(UUID id){return Optional.empty();}}
}
